import { CATEGORIES } from './data.js';
import { money, dateLabel, daysUntil, monthlyCost, forecastAnnual, getMetrics, getAttention, getVisibleSubscriptions } from './domain.js';
import { icon } from './icons.js';

const esc = (value = '') => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const amount = value => money(value, Number.isInteger(value) ? 0 : 2);
const btn = (label, action, { kind = 'secondary', cls = '', attrs = '', glyph = '', trailing = false } = {}) => `<button type="button" class="btn button btn-${kind} ${kind} ${cls}" data-action="${action}" ${attrs}>${glyph && !trailing ? icon(glyph,18) : ''}<span>${label}</span>${glyph && trailing ? icon(glyph,18) : ''}</button>`;
const logo = (sub, size = '') => `<span class="service-logo service-icon ${size}" style="--service-color:${esc(sub.brand)}" aria-hidden="true">${esc(sub.logo)}</span>`;
const brand = () => `<span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 32 32" fill="none"><path d="M8 17.5 13.2 23 25 10" stroke="currentColor" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M9 8h8" stroke="currentColor" stroke-width="3.5" stroke-linecap="round"/></svg></span><span class="brand-wordmark">SubsNotes<span>SUBSCRIPTION CLARITY</span></span>`;
const navButton = (view, label, glyph, current) => `<button type="button" class="nav-item ${current === view ? 'active' : ''}" data-action="navigate" data-view="${view}" ${current === view ? 'aria-current="page"' : ''}>${icon(glyph,20)}<span>${label}</span></button>`;
const countdown = (date) => { const days = daysUntil(date); return days < 0 ? 'Past due' : days === 0 ? 'Today' : `In ${days} day${days === 1 ? '' : 's'}`; };
const badge = (text, kind = '') => `<span class="badge ${kind}">${text}</span>`;
const riskInfo = sub => sub.risk === 'payment' ? {label:'Payment issue',kind:'danger',glyph:'alert',heading:'Keep your work moving',body:'A payment failed. The next retry is approaching.',action:'Review payment'} : sub.risk === 'promo' ? {label:'Offer ending',kind:'warning',glyph:'sparkles',heading:`${amount(sub.amount)} → ${amount(sub.promo?.regularPrice ?? sub.amount)}/mo`,body:'Your monthly discount ends before the next bill.',action:'Review offer'} : {label:'Renewing soon',kind:'neutral',glyph:'calendar',heading:`${amount(sub.amount)}/${sub.cadence === 'annual' ? 'yr' : 'mo'} renewal coming up`,body:'Decide whether to keep it before the next charge.',action:'Review renewal'};

function landing(state) {
  const metrics = getMetrics(state);
  return `<div class="landing">
    <header class="landing-header landing-nav"><a href="#" class="brand" data-action="navigate" data-view="landing" aria-label="SubsNotes home">${brand()}</a><div class="landing-nav-actions"><span class="demo-pill"><span class="status-dot"></span>Interactive demo</span>${btn('Try the demo', 'navigate', {kind:'primary',attrs:'data-view="overview"',glyph:'arrow-right',trailing:true})}</div></header>
    <main id="main-content" tabindex="-1">
      <section class="landing-hero"><div class="hero-copy"><p class="eyebrow"><span class="eyebrow-line"></span> A LITTLE CLARITY. BEFORE YOU RENEW.</p><h1>More subscriptions.<br>Fewer surprises.</h1><p class="hero-description">See your costs, expiring offers, and upcoming renewals.<br class="desktop-break">Make the call before the next charge.</p><div class="hero-actions">${btn('Try the demo', 'navigate', {kind:'primary',cls:'btn-large',attrs:'data-view="overview"',glyph:'arrow-right',trailing:true})}<span class="hero-reassurance">No sign-up · Sample data</span></div><div class="hero-proof"><span class="proof-icon">${icon('shield',18)}</span><p>Explore freely. Changes stay in your browser.<br>No accounts connected. No real charges or cancellations.</p></div></div>
      <div class="hero-preview" aria-label="Preview of the demo dashboard"><div class="preview-window"><div class="preview-topbar"><span class="preview-mini-brand">${brand()}</span><span class="preview-date">Friday, October 23</span></div><div class="preview-heading"><div><p class="eyebrow">YOUR MONTHLY PICTURE</p><h2>Every subscription, in view.</h2></div><span class="preview-live-dot">Sample data</span></div><div class="preview-total"><span>Monthly equivalent <small>USD</small></span><strong>${money(metrics.monthly,2)}<span>/mo</span></strong></div><div class="preview-chart" aria-hidden="true">${metrics.categories.map((c,i)=>`<i style="--segment:${c.percent}%;--bar-color:${['#224f40','#819d76','#c9d8b9','#d9c5a7'][i]}"></i>`).join('')}</div><div class="preview-list">${state.subscriptions.slice(0,3).map(sub => `<div class="preview-row">${logo(sub)}<div><strong>${esc(sub.name)}</strong><small>${esc(sub.plan)}</small></div><span>${amount(sub.amount)}<small>/${sub.cadence === 'annual' ? 'yr' : 'mo'}</small></span></div>`).join('')}</div><div class="preview-note">${icon('check',15)} Clear costs. Clear next steps.</div></div><div class="floating-card"><span class="floating-icon">${icon('bell',22)}</span><div><strong>An offer is ending</strong><p>Canva · Standard price in 9 days</p></div><span class="floating-check">${icon('check',16)}</span></div></div></section>
      <section class="landing-features" aria-label="What you can explore in the demo"><article class="feature-card"><span class="feature-number">01 / SEE THE WHOLE PICTURE</span><h2>See the whole picture.</h2><p>Compare services, categories, and monthly costs, including annual plans.</p></article><article class="feature-card"><span class="feature-number">02 / CATCH THE CHANGE</span><h2>Catch the important changes.</h2><p>Upcoming renewals, expiring offers, and payment issues rise to the top.</p></article><article class="feature-card"><span class="feature-number">03 / MAKE THE CALL</span><h2>Turn a reminder into a decision.</h2><p>Review the terms, choose what to keep, and leave a clear record of your decision.</p></article></section>
      <section class="landing-invitation"><div><p class="eyebrow">BUILT FOR A CALMER WORKDAY</p><h2>Keep your tools working for you.<br class="mobile-only"> Stay ahead of their bills.</h2></div>${btn('Explore the demo', 'navigate', {kind:'primary',attrs:'data-view="overview"',glyph:'arrow-right',trailing:true})}</section>
    </main><footer class="landing-footer"><span>SubsNotes</span><p>Interactive concept · Illustrative prices and terms, not current vendor offers</p><button type="button" class="text-button" data-action="feedback">Share your thoughts ${icon('arrow-up-right',15)}</button></footer>
  </div>`;
}

function shell(state,ui,content) {
  const attention = getAttention(state).length;
  return `<div class="app-shell"><aside class="sidebar" aria-label="Main navigation"><a href="#" class="brand" data-action="navigate" data-view="landing" aria-label="Return to SubsNotes home">${brand()}</a><div class="sidebar-workspace"><span class="workspace-avatar">T</span><div><strong>My workspace</strong><span>Personal demo account</span></div><span class="workspace-check">${icon('check',14)}</span></div><nav class="main-nav">${navButton('overview','Overview','grid',ui.view)}${navButton('subscriptions','Subscriptions','layers',ui.view)}${navButton('reminders','Reminders','bell',ui.view)}</nav><div class="sidebar-note"><span class="sidebar-note-icon">${icon('sparkles',21)}</span><strong>A little more clarity.<br>A little less surprise.</strong><p>Make every renewal intentional.</p></div><div class="sidebar-footer">${btn('Give feedback','feedback',{kind:'ghost',glyph:'message'})}${btn('Export demo data','export',{kind:'ghost',glyph:'download'})}<div class="sidebar-demo-note"><span class="status-dot"></span>Local demo · Nothing is sent</div></div></aside>
  <div class="workspace"><header class="topbar"><div class="breadcrumbs"><span>My workspace</span>${icon('chevron-right',13)}<strong>${ui.view === 'overview' ? 'Overview' : ui.view === 'subscriptions' ? 'Subscriptions' : 'Reminders'}</strong></div><div class="topbar-actions"><span class="demo-pill">DEMO <span class="demo-date">· 2026.10.23</span></span><button type="button" class="icon-button" data-action="reset" aria-label="Reset demo data" title="Reset demo data">${icon('refresh',17)}</button><button type="button" class="avatar-button" data-action="feedback" aria-label="Share demo feedback">T</button></div></header><main id="main-content" class="main-content" tabindex="-1">${content}<footer class="workspace-footer"><span><span class="status-dot"></span>Sample data · Fixed date: October 23, 2026</span><button type="button" class="text-button" data-action="feedback">Give feedback ${icon('arrow-up-right',14)}</button></footer></main></div></div>`;
}

function metricsCards(state,ui) {
  const m = getMetrics(state);
  const isAnnual = ui.period === 'annual';
  return `<div class="metrics-grid"><article class="metric-card metric-primary"><div class="metric-topline"><span>${isAnnual ? 'Next 12 months' : 'Monthly equivalent'}</span><span class="currency-label">USD</span></div><div class="metric-number">${money(isAnnual ? m.annual : m.monthly,2)}<span>/${isAnnual ? '12 months' : 'mo'}</span></div><div class="metric-bottom"><p>${isAnnual ? 'Based on renewal and offer schedules' : 'Annual plans spread monthly; renewals off excluded'}</p><div class="segmented segmented-small" aria-label="Spending display period"><button type="button" data-action="period" data-period="monthly" aria-pressed="${!isAnnual}" class="${!isAnnual ? 'selected' : ''}">Month</button><button type="button" data-action="period" data-period="annual" aria-pressed="${isAnnual}" class="${isAnnual ? 'selected' : ''}">Year</button></div></div></article><article class="metric-card"><div class="metric-topline"><span>Active subscriptions</span><span class="metric-icon">${icon('layers',18)}</span></div><div class="metric-number">${m.count}<span>services</span></div><div class="metric-bottom"><p>Across ${m.categories.filter(c=>c.amount>0).length} categories</p><button type="button" class="text-button" data-action="navigate" data-view="subscriptions" aria-label="View all subscriptions">View ${icon('arrow-right',14)}</button></div></article><article class="metric-card"><div class="metric-topline"><span>Needs attention</span><span class="metric-icon ${m.attentionCount ? 'amber' : ''}">${icon(m.attentionCount ? 'bell' : 'check',18)}</span></div><div class="metric-number">${m.attentionCount}<span>to review</span></div><div class="metric-bottom"><p>${m.attentionCount ? 'Renewals, offers, or payment changes' : 'All caught up. A little peace of mind.'}</p><span class="metric-dots" aria-hidden="true">${Array.from({length:Math.min(m.attentionCount,3)},()=>'<i></i>').join('')}</span></div></article></div>`;
}

function attentionCard(sub) {
  const info = riskInfo(sub);
  return `<article class="attention-card ${info.kind}"><div class="attention-top">${badge(`${icon(info.glyph,12)} ${info.label}`,info.kind)}<span class="countdown">${countdown(sub.risk === 'promo' ? sub.promo.end : sub.nextDate)}</span></div><div class="attention-service">${logo(sub)}<div><h3>${esc(sub.name)}</h3><span>${esc(sub.plan)}</span></div></div><h4>${info.heading}</h4><p>${info.body}</p><button type="button" class="attention-link" data-action="detail" data-id="${esc(sub.id)}"><span>${info.action}</span>${icon('arrow-right',16)}</button></article>`;
}

function categoryPanel(state) {
  const m = getMetrics(state);
  const colors = ['#2d5746','#9cb18e','#c6d0aa','#dcc6a6'];
  let current=0;
  const stops=m.categories.map((c,i)=>{const start=current;current+=c.percent;return `${colors[i]} ${start}% ${current}%`;}).join(',');
  return `<section class="panel category-panel"><div class="section-heading"><h2>Spending by category</h2><span class="subtle-label">Monthly equivalent</span></div><div class="category-chart" style="--chart-fill:conic-gradient(${stops || '#e6eedf 0% 100%'})" role="img" aria-label="Monthly equivalent costs by category, listed below"><div class="donut-center"><span>Monthly total</span><strong>${money(m.monthly,2)}</strong><small>USD</small></div></div><ul class="category-list category-legend">${m.categories.map((c,i)=>`<li><button type="button" data-action="filter" data-filter="${esc(c.name)}" aria-label="View ${esc(c.name)} subscriptions"><span class="category-dot" style="--category-color:${colors[i]}"></span><span>${esc(c.name)}</span><strong>${money(c.amount,2)}</strong><small>${Math.round(c.percent)}%</small></button></li>`).join('')}</ul></section>`;
}

function renewalPanel(state) {
  const items = getVisibleSubscriptions(state,{filter:'all',query:'',sort:'date'}).filter(s=>s.status!=='cancelled' && s.autoRenew).slice(0,3);
  return `<section class="panel renewal-panel"><div class="section-heading"><h2>Upcoming charges</h2>${icon('calendar',17)}</div><ol class="renewal-list timeline">${items.map(s=>`<li><span class="timeline-dot"></span><div class="renewal-date">${dateLabel(s.nextDate)}</div><button type="button" data-action="detail" data-id="${esc(s.id)}"><span>${esc(s.name)}</span><strong>${amount(s.risk === 'promo' && s.promo ? s.promo.regularPrice : s.amount)}</strong></button></li>`).join('')}</ol><p class="fine-print">Estimated from sample billing dates. No real charges.</p></section>`;
}

function subscriptionStatus(sub) {
  if(sub.status === 'cancelled' || !sub.autoRenew) return badge('Renewal off','success');
  if(sub.decision === 'cancel-intent') return badge('Cancellation pending','warning');
  if(sub.risk) {const info=riskInfo(sub);return badge(info.label,info.kind);}
  return badge(sub.decision === 'keep' ? 'Keeping' : 'Active','quiet');
}
function subscriptionTable(items,{compact=false}={}) {
  if(!items.length) return `<div class="empty-state"><span class="empty-icon">${icon('search',28)}</span><h3>No matching subscriptions</h3><p>Try another search or show all subscriptions.</p>${btn('Show all subscriptions','reset-filters',{kind:'secondary'})}</div>`;
  return `<div class="table-wrap"><table class="subscription-table ${compact?'compact':''}"><thead><tr><th scope="col">Service</th><th scope="col" class="category-column">Category</th><th scope="col">Price</th><th scope="col" class="date-column">Next date</th><th scope="col" class="status-column">Status</th><th scope="col"><span class="sr-only">View details</span></th></tr></thead><tbody>${items.map(s=>`<tr><td><button type="button" class="service-cell" data-action="detail" data-id="${esc(s.id)}" aria-label="View ${esc(s.name)} subscription details">${logo(s)}<span><strong>${esc(s.name)}${s.essential?'<span class="essential-dot" title="Essential"></span>':''}</strong><small>${esc(s.plan)}</small></span></button></td><td class="category-column"><span class="category-text">${esc(s.category)}</span></td><td><span class="cost-value">${amount(s.amount)}<small>/${s.cadence==='annual'?'yr':'mo'}</small></span><span class="cost-subline">${s.promo?'Promotional price':s.cadence==='annual'?`About ${money(monthlyCost(s),2)}/mo`:'Billed monthly'}</span></td><td class="date-column"><span class="table-date">${dateLabel(s.nextDate)}</span><small class="date-subline">${!s.autoRenew?'Access ends':countdown(s.nextDate)}</small></td><td class="status-column">${subscriptionStatus(s)}</td><td><button type="button" class="icon-button row-action" data-action="detail" data-id="${esc(s.id)}" aria-label="View ${esc(s.name)} details">${icon('chevron-right',17)}</button></td></tr>`).join('')}</tbody></table></div>`;
}

function overview(state,ui) {
  const attention=getAttention(state);
  const subs=getVisibleSubscriptions(state,{filter:'all',query:'',sort:'date'}).filter(s=>s.status!=='cancelled').slice(0,4);
  return `<section class="page-heading"><div><p class="eyebrow">FRIDAY, OCTOBER 23</p><h1>A clearer view of what is next.</h1><p>${attention.length ? `${attention.length} subscriptions need a look. A small check now can prevent a surprise later.` : 'You are all caught up. Your next decision can wait.'}</p></div>${btn('Simulate scan','scan',{glyph:'refresh',kind:'secondary'})}</section>${metricsCards(state,ui)}
    <div class="overview-grid dashboard-grid"><div class="dashboard-main"><section class="attention-section"><div class="section-heading"><div class="heading-with-count"><h2>A little attention now</h2><span class="count-pill">${attention.length}</span></div><span class="subtle-label">Prioritized for you</span></div>${attention.length?`<div class="attention-grid">${attention.map(attentionCard).join('')}</div>`:`<div class="all-clear"><span>${icon('check',26)}</span><div><h3>Nothing needs your attention</h3><p>Your decisions and reminder preferences stay in this browser.</p></div></div>`}</section><section class="panel subscriptions-panel"><div class="section-heading"><h2>Your subscriptions</h2><button type="button" class="text-button" data-action="navigate" data-view="subscriptions">View all ${icon('arrow-right',15)}</button></div>${subscriptionTable(subs,{compact:true})}<div class="panel-footnote">${icon('info',14)}Illustrative USD prices. Annual charges and monthly equivalents are shown separately.</div></section><div class="insight-note"><span class="insight-icon">${icon('shield',19)}</span><p><strong>Every decision has context.</strong> Open a subscription to see sample billing evidence, offer terms, and activity.</p></div></div><aside class="dashboard-aside" aria-label="Spending and upcoming charges">${categoryPanel(state)}${renewalPanel(state)}</aside></div>`;
}

function subscriptions(state,ui) {
  const items=getVisibleSubscriptions(state,{filter:ui.filter,query:ui.query,sort:ui.sort});
  const activeCount=state.subscriptions.filter(s=>s.status!=='cancelled').length;
  const attention=getAttention(state).length;
  return `<section class="page-heading"><div><p class="eyebrow">A HOME FOR EVERY SUBSCRIPTION</p><h1>Every subscription, in view.</h1><p>${activeCount} active subscriptions across ${CATEGORIES.length} categories. Find the next one to review.</p></div>${btn('Simulate scan','scan',{glyph:'refresh'})}</section><section class="panel subscription-list-panel"><div class="list-toolbar"><div class="filter-tabs" aria-label="Filter subscriptions by status">${[['all','All'],['attention',`Needs attention <span>${attention}</span>`],['cancelled','Renewal off']].map(([f,label])=>`<button type="button" data-action="filter" data-filter="${f}" aria-pressed="${ui.filter===f}" class="filter-tab ${ui.filter===f?'active':''}">${label}</button>`).join('')}</div><div class="search-field">${icon('search',17)}<label class="sr-only" for="subscription-query">Search service names or plans</label><input id="subscription-query" name="query" type="search" value="${esc(ui.query)}" placeholder="Search services or plans" autocomplete="off"></div></div><div class="list-secondary-toolbar"><div class="category-filters" aria-label="Filter by category">${CATEGORIES.map(c=>`<button type="button" class="category-chip ${ui.filter===c?'active':''}" data-action="filter" data-filter="${esc(c)}" aria-pressed="${ui.filter===c}">${esc(c)}</button>`).join('')}</div><label class="sort-control">Sort<select name="sort" aria-label="Sort subscriptions"><option value="date" ${ui.sort==='date'?'selected':''}>Next date</option><option value="amount" ${ui.sort==='amount'?'selected':''}>Monthly cost: high to low</option><option value="name" ${ui.sort==='name'?'selected':''}>Service name</option></select></label></div>${subscriptionTable(items)}<div class="panel-footnote"><span>Showing ${items.length} subscriptions · Prices in USD</span><span>Illustrative prices, not current vendor offers</span></div></section><div class="insight-note"><span class="insight-icon">${icon('info',19)}</span><p>Plans with renewal off remain in the list. No new renewal is expected in this demo, but access may continue until the paid period ends.</p></div>`;
}

function reminders(state) {
  const p=state.preferences;
  return `<section class="page-heading"><div><p class="eyebrow">A NUDGE, AT THE RIGHT TIME</p><h1>A nudge, at the right time.</h1><p>Stay on top of the important things. Leave room for focused work.</p></div>${btn('Preview alert','preview-notification',{glyph:'bell'})}</section><div class="settings-layout"><form class="panel settings-panel" data-form="preferences"><div class="section-heading"><h2>Reminder preferences</h2>${badge('Saved locally','quiet')}</div><div class="form-field reminder-days"><label for="reminder-days">How much notice would you like?</label><p>Applies to known renewal dates and offer end dates.</p><select name="days" id="reminder-days">${[1,3,7,14].map(d=>`<option value="${d}" ${p.days===d?'selected':''}>${d} day${d === 1 ? '' : 's'} before</option>`).join('')}</select></div><div class="toggle-list">${[['email','Email reminders','A reminder before a renewal or offer ends.','mail'],['weekly','Weekly summary','One digest of upcoming costs and changes.','calendar'],['quiet','Quiet hours','Pause routine reminders from 10 pm to 8 am (Taipei time).','clock']].map(([name,title,description,glyph])=>`<label class="toggle-row" for="pref-${name}"><span class="toggle-icon">${icon(glyph,20)}</span><span class="toggle-copy"><strong>${title}</strong><small>${description}</small></span><span class="toggle-control"><input type="checkbox" name="${name}" id="pref-${name}" ${p[name]?'checked':''}><span class="toggle-track" aria-hidden="true"></span></span></label>`).join('')}</div><div class="settings-footer"><p>${icon('info',15)}This demo saves preferences. It does not send notifications.</p><button type="submit" class="btn button btn-primary primary">${icon('check',18)}<span>Save preferences</span></button></div></form><aside class="settings-aside"><section class="notification-preview"><div class="notification-preview-header"><span class="preview-app-icon">${icon('bell',19)}</span><span>SubsNotes · Sample alert</span><small>Now</small></div><h2>A little time before you renew.</h2><p>Notion renews on October 28 for US$96 a year. Keep it, or take a moment to review your needs?</p><button type="button" class="notification-example-action" data-action="detail" data-id="notion">View subscription ${icon('arrow-right',15)}</button><div class="notification-preview-bottom">A sample notification. Nothing will be sent.</div></section><section class="reminder-explainer"><span class="eyebrow">LESS NOISE, MORE CLARITY</span><h3>Useful reminders. Less noise.</h3><p>Renewals, expiring offers, and payment issues each need a different response. Preview a reminder, then explore the next step.</p></section><section class="panel local-data-panel"><h3>Your demo data</h3><p>Changes and feedback stay in this browser. Export them to share with the product team.</p>${btn('Export data and feedback','export',{glyph:'download',kind:'secondary'})}</section></aside></div>`;
}

function dialogHeader(title, eyebrow='', cls='') {
  return `<header class="modal-header ${cls}"><div>${eyebrow?`<p class="eyebrow">${eyebrow}</p>`:''}<h2 id="dialog-title">${title}</h2></div><button type="button" class="icon-button close-dialog" data-action="close-modal" aria-label="Close dialog">${icon('close',20)}</button></header>`;
}

function subscriptionDetail(state,ui) {
  const s=state.subscriptions.find(s=>s.id===ui.modal.id);
  if(!s) return `${dialogHeader('Subscription not found')}<div class="modal-body"><p>Close this dialog and select a subscription again.</p></div>`;
  const cancelled=s.status==='cancelled'||!s.autoRenew;
  const info=riskInfo(s);
  const actions=cancelled?btn('Done','close-modal',{kind:'primary',glyph:'check'}):s.decision==='cancel-intent'?btn('Simulate renewal off','simulate-cancel',{kind:'primary',attrs:`data-id="${esc(s.id)}"`,glyph:'check'}):s.risk==='payment'?btn('Simulate payment update','resolve-payment',{kind:'primary',attrs:`data-id="${esc(s.id)}"`,glyph:'credit-card'}):s.risk==='promo'?btn('Adjust reminders','reminder-settings',{kind:'primary',glyph:'bell'}):s.risk==='renewal'?btn('Keep subscription','keep',{kind:'primary',attrs:`data-id="${esc(s.id)}"`,glyph:'check'}):btn('Done','close-modal',{kind:'primary',glyph:'check'});
  return `${dialogHeader('Subscription details','SUBSCRIPTION, WITH CONTEXT')}<div class="modal-body"><div class="detail-summary">${logo(s,'large')}<div><div class="detail-name"><h3>${esc(s.name)}</h3>${s.essential?badge('Essential','quiet'):''}</div><p>${esc(s.plan)} · ${esc(s.category)}</p></div><div class="detail-price"><strong>${amount(s.amount)}</strong><span>USD/${s.cadence==='annual'?'yr':'mo'}</span></div></div>
    ${cancelled?`<div class="notice success">${icon('check',20)}<div><strong>Renewal is off in this demo</strong><p>Only this local demo was updated. Sample access continues until ${dateLabel(s.nextDate)}. No real account was changed.</p></div></div>`:s.decision==='cancel-intent'?`<div class="notice warning">${icon('clock',20)}<div><strong>Decision recorded. Cancellation is not confirmed.</strong><p>You would still need to cancel with the provider. Here, you can simulate receiving confirmation to see what happens next.</p></div></div>`:s.risk?`<div class="notice ${info.kind}">${icon(info.glyph,20)}<div><strong>${s.risk==='payment'?'Payment failed. An essential service may be interrupted.':s.risk==='promo'?`Offer ends ${countdown(s.promo.end).toLowerCase()}, then ${amount(s.promo.regularPrice)}/mo`:`Renews ${countdown(s.nextDate).toLowerCase()} for ${amount(s.amount)}`}</strong><p>${s.risk==='payment'?'The sample notice shows a failed payment. After updating the payment method, you would still need confirmation from the provider.':s.risk==='promo'?'Review the offer and cancellation terms before deciding.':'Decide whether you still need this service before the next charge.'}</p></div></div>`:`<div class="notice success">${icon('check',20)}<div><strong>${s.decision==='keep'?'Your decision to keep this is saved':'No issues to review'}</strong><p>This is a demo state. No accounts are connected or real payments verified.</p></div></div>`}
    <div class="detail-grid"><div class="detail-fact"><span>${cancelled?'Access ends':'Next billing date'}</span><strong>${dateLabel(s.nextDate)}</strong><small>${esc(s.nextDate.slice(0,4))} · ${countdown(s.nextDate)}</small></div><div class="detail-fact"><span>Monthly equivalent</span><strong>${money(monthlyCost(s),2)} <small>USD</small></strong><small>${s.cadence==='annual'?'Annual fee divided by 12':'Current monthly price'}</small></div><div class="detail-fact"><span>Auto-renewal</span><strong>${s.autoRenew?'On':'Off'}</strong><small>${cancelled?'Demo action confirmed':'Sample account data'}</small></div><div class="detail-fact"><span>Next 12 months</span><strong>${money(forecastAnnual(s),2)} <small>USD</small></strong><small>${cancelled?'No further renewal charges':'Current schedule; extra usage excluded'}</small></div></div>
    ${s.promo?`<section class="detail-section promo-section"><div class="section-heading"><h3>How does the price change?</h3>${badge('Sample terms','quiet')}</div><div class="price-timeline"><div class="price-phase current"><span class="phase-dot"></span><small>Now · Promotional price</small><strong>${amount(s.amount)}<span>/mo</span></strong><p>Discount applies until ${dateLabel(s.promo.end)}</p></div><span class="phase-arrow">${icon('arrow-right',20)}</span><div class="price-phase"><span class="phase-dot"></span><small>From ${dateLabel(s.promo.end)}</small><strong>${amount(s.promo.regularPrice)}<span>/mo</span></strong><p>Standard sample monthly price</p></div></div><div class="promo-terms"><strong>What happens if you cancel early?</strong><p>${esc(s.promo.cancelPolicy)}</p><p class="fine-print">${esc(s.promo.terms)}</p></div></section>`:''}
    <section class="detail-section"><button type="button" class="evidence-toggle" data-action="evidence" aria-expanded="${ui.showEvidence}" aria-controls="evidence-content"><span>${icon('mail',18)}View evidence and sample email</span>${icon('chevron-down',17)}</button>${ui.showEvidence?`<div id="evidence-content" class="evidence-panel"><div class="evidence-meta"><strong>${esc(s.source)}</strong><span>${dateLabel(s.evidenceDate)}</span></div><p>${s.id==='github'?`Your ${esc(s.name)} subscription payment failed. We will retry on ${dateLabel(s.nextDate)}. Please check your payment method.`:s.promo?`Your monthly offer ends on ${dateLabel(s.promo.end)}. Each following period will be billed at US${amount(s.promo.regularPrice)}.`:`Your ${esc(s.name)} ${esc(s.plan)} subscription renews on ${dateLabel(s.nextDate)}, with an expected charge of US${amount(s.amount)}.`}</p><div class="evidence-disclaimer">${icon('info',14)}Fictional email, not a real provider notice. Prices and terms are illustrative.</div></div>`:''}</section>
    ${state.activity.filter(a=>a.subscriptionId===s.id).length?`<section class="detail-section activity-section"><h3>Activity</h3><ul>${state.activity.filter(a=>a.subscriptionId===s.id).slice(-3).reverse().map(a=>`<li>${icon('check',14)}<span>${esc(a.message)}</span></li>`).join('')}</ul></section>`:''}
    <p class="detail-demo-note">${icon('shield',14)}Actions only change demo data. No provider is contacted and no notification is sent.</p></div><footer class="modal-footer"><div>${!cancelled&&s.decision!=='cancel-intent'?btn('Do not renew','cancel-intent',{kind:'ghost',attrs:`data-id="${esc(s.id)}"`}):btn('Back','close-modal',{kind:'ghost'})}</div><div>${actions}</div></footer>`;
}

function scanDialog(ui) {
  const steps=['Prepare 8 sample subscriptions','Organize billing and offer details','Flag changes to review'];
  return `${dialogHeader(ui.scanDone?'Your sample data is ready':'See how a scan could work','SIMULATED SCAN')}<div class="modal-body scan-body"><div class="scan-visual ${ui.scanDone?'done':''}">${icon(ui.scanDone?'check':'layers',32)}<span></span></div><h3>${ui.scanDone?'Your subscriptions are ready.':'Organizing sample data…'}</h3><p>This is a local animation. No inbox is being read.</p><ol class="scan-steps">${steps.map((s,i)=>`<li class="${ui.scanDone||ui.scanStep>i?'complete':ui.scanStep===i?'current':''}"><span>${ui.scanDone||ui.scanStep>i?icon('check',15):i+1}</span><div><strong>${s}</strong><small>${i===0?'Using built-in sample data':i===1?'No external connections':'Keeping your existing demo decisions'}</small></div></li>`).join('')}</ol><div class="notice neutral">${icon('shield',19)}<p>A connected product would need your permission. This demo asks for no account, password, or API key.</p></div></div><footer class="modal-footer"><span class="fine-print">Simulated flow · Nothing is sent</span>${ui.scanDone?btn('Back to overview','scan-finish',{kind:'primary',glyph:'arrow-right',trailing:true}):btn('Close for now','close-modal',{kind:'secondary'})}</footer>`;
}

function feedbackDialog(state,ui) {
  return `${dialogHeader('Help shape what comes next.','MAKE THIS MORE USEFUL')}<form data-form="feedback"><div class="modal-body"><p class="feedback-intro">Did this demo help you understand your subscriptions and what to do next?</p><fieldset class="rating-fieldset"><legend>How useful is this concept to you?</legend><div class="rating-buttons">${[1,2,3,4,5].map(n=>`<button type="button" class="rating-button ${ui.rating===n?'selected':''}" data-action="rating" data-value="${n}" aria-pressed="${ui.rating===n}" aria-label="${n} out of 5">${n}</button>`).join('')}</div><div class="rating-scale"><span>Not useful yet</span><span>Very useful</span></div></fieldset><div class="form-field"><label for="feedback-message">What was useful, or confusing?</label><textarea id="feedback-message" name="message" rows="4" maxlength="2000" required placeholder="For example: I want to see how much more I will pay after an offer ends…">${esc(ui.feedbackMessage || '')}</textarea></div><div class="notice neutral">${icon('info',18)}<p>Feedback stays in this browser. It is not sent to the team automatically. Save it, then export a JSON file to share.</p></div>${state.feedback.length?`<p class="fine-print">${state.feedback.length} feedback entries are saved in this browser.</p>`:''}</div><footer class="modal-footer">${btn('Export data','export',{kind:'ghost',glyph:'download'})}<button type="submit" class="btn button btn-primary primary">${icon('check',17)}<span>Save feedback locally</span></button></footer></form>`;
}

export function renderApp(state,ui) {
  if(ui.view==='landing') return landing(state);
  const content=ui.view==='subscriptions'?subscriptions(state,ui):ui.view==='reminders'?reminders(state):overview(state,ui);
  return shell(state,ui,content);
}

export function renderOverlay(state,ui) {
  if(!ui.modal) return '';
  let content;
  switch(ui.modal.type) {
    case 'subscription': content=subscriptionDetail(state,ui); break;
    case 'scan': content=scanDialog(ui); break;
    case 'feedback': content=feedbackDialog(state,ui); break;
    case 'export': content=`${dialogHeader('Take your feedback with you','YOUR DATA, IN YOUR HANDS')}<div class="modal-body"><p class="feedback-intro">Includes the current demo state and ${state.feedback.length} saved feedback entries. Download or copy it to share. Nothing is sent automatically.</p><div class="form-field"><label for="export-json">Copyable JSON data</label><textarea id="export-json" rows="10" readonly spellcheck="false" style="font-family:ui-monospace,monospace;font-size:12px">${esc(ui.exportText||'')}</textarea></div></div><footer class="modal-footer">${btn('Copy JSON','copy-export',{kind:'secondary',glyph:'layers'})}${btn('Download JSON','download-json',{kind:'primary',glyph:'download'})}</footer>`; break;
    case 'reset': content=`${dialogHeader('Start fresh?','A FRESH START')}<div class="modal-body"><div class="notice warning">${icon('refresh',20)}<p>This resets your subscription decisions, reminder preferences, and local feedback. No real accounts are affected.</p></div><p class="fine-print">Want to keep your feedback? Export the demo data first.</p></div><footer class="modal-footer">${btn('Export first','export',{kind:'ghost',glyph:'download'})}<div class="modal-action-group">${btn('Keep my changes','close-modal')}${btn('Reset demo data','confirm-reset',{kind:'primary'})}</div></footer>`; break;
    default: return '';
  }
  return `<dialog id="app-dialog" class="app-dialog ${ui.modal.type}-dialog" aria-labelledby="dialog-title">${content}</dialog>`;
}
